cat > corpus/projects/f32-dsp/scripts/compare.js <<'EOF'
// Measure fixed impulse inputs on a fresh copy with the checked speed pipeline.
const options = { chains: true, coalesce: true, homes: true };
const { inputs } = JSON.parse(project.files.read('project.json'));
const work = Array(64).fill(0);
work[13] = 0x3f80; // Real part of complex sample 3 is 1.0.
work[15] = 0xbf00; // Imaginary part is -0.5.
const samples = Array(32).fill(0);
samples[1] = 0x3f80;
const cases = [
  ['fft', [work, inputs.fft.twiddles.cells, 16]],
  ['biquadBank', [samples, inputs.biquadBank.coefficients.cells, Array(64).fill(0)]],
];

const before = p.compile(options);
const run = p.pipeline('speed', { count: 40 });
const rejected = run.steps.filter(step => step.rejected);
if (rejected.length) throw new Error(rejected.map(step => step.pass + ': ' + step.rejected).join('
'));
const after = p.compile(options);

return cases.map(([fn, args]) => {
  const baseline = before.run(fn, args);
  const optimized = after.run(fn, args);
  if (baseline.trap || optimized.trap) throw new Error(fn + ': ' + (baseline.trap || optimized.trap));
  return { fn, r0Instructions: baseline.steps, speedInstructions: optimized.steps };
});
EOF
cat > corpus/projects/f32-dsp/notes.md <<'EOF'
# f32 DSP

`fft` computes an unnormalized forward complex transform for `n = 8` or
`16`. It works in place in a 32-float buffer with alternating real and
imaginary lanes. At size 8 it leaves the final 16 floats untouched. Its
read-only table contains the first eight complex roots for size 16.
The butterfly's `stride` selects the roots for the current stage.

`biquadBank` runs two direct-form-I filters over the same 16 real samples.
Each coefficient row is `b0, b1, b2, a1, a2`, with denominator
`1 + a1*z^-1 + a2*z^-2`. Each band starts with zero history and writes
16 consecutive floats starting at `16 * band`. The samples and
coefficients are read-only.

Each float occupies two u16 cells, low half first. Generated samples
are finite and lie in `[-1, 1]`. Each call uses separate buffers.

Follow `tr` and `ti` from the butterfly's products to its four stores.
In the filter, compare the call to `dot3` at r0 with the inlined
multiply-add chain after `speed`. The `compare` script reports RV32
instructions for a fixed input to each kernel on a fresh copy.
EOF
sed -i 's/^    "distinct"$/    "distinct",
