console.log(await b.specialize(createArtifact(BindingsIR, id, { formatVersion: 1, source: id, bindings: [{ fn: 'fft', param: 'n', value: 16, entity: 'f32-dsp#fft16' }] })));
for (const p of [a, b]) {
